@property
def is_stopped(self) -> bool:
    """Returns ``True`` if the State is categorized as Stopped."""
    return self in {
        TorrentState.PAUSED_UPLOAD,
        TorrentState.STOPPED_UPLOAD,
        TorrentState.PAUSED_DOWNLOAD,
        TorrentState.STOPPED_DOWNLOAD,
    }
